/*
 * test_forward.c -- parity harness for the C99 reference implementation.
 *
 * Compares jev_forward + jev_answer + jev_decode against the vectors exported by
 * Python (c/test_vectors.h, generated by scripts/18_export_c.py).  Exit code 0
 * means every case is inside tolerance; 1 means a real mismatch.
 *
 *   gcc -std=c99 -O2 -o test_forward test_forward.c jev_head.c -lm
 *   ./test_forward
 */
#include <math.h>
#include <stdio.h>

#include "jev_head.h"
#include "test_vectors.h"

int main(void) {
    int c, i, a, failures = 0;
    float worst_logits = 0.0f, worst_probs = 0.0f, worst_step = 0.0f;
    jev_policy pol;
    int escalations = 0;
    pol.tau_act = JEV_TV_TAU_ACT;
    pol.tau_esc = JEV_TV_TAU_ESC;
    pol.tau_noul = JEV_TV_TAU_NOUL;

    for (c = 0; c < JEV_TV_N; ++c) {
        jev_state s;
        jev_logits lg;
        jev_probs p;
        jev_action act;
        float got_logits[1][21];
        float got_probs[1][21];
        float got_step[1][3];

        for (i = 0; i < JEV_N_FEATS; ++i) {
            s.feats[i] = JEV_TV_FEATS[c][i];
        }
        for (i = 0; i < JEV_N_CURVE; ++i) {
            s.curves[0][i] = JEV_TV_CURVES[c][i];
            s.curves[1][i] = JEV_TV_CURVES[c][JEV_N_CURVE + i];
        }

        jev_forward(&s, &lg);
        jev_answer(&lg, JEV_TV_TEMP, &p);
        jev_decode(&p, &act);
        jev_abstain(&act, &p, &pol, &escalations);

        for (a = 0; a < 3; ++a) {
            for (i = 0; i < JEV_K; ++i) {
                got_logits[0][a * JEV_K + i] = lg.choice[a][i];
                got_probs[0][a * JEV_K + i] = p.choice[a][i];
            }
            got_step[0][a] = act.step[a];
        }

        {
            float dl = 0.0f, dp = 0.0f, ds = 0.0f;
            for (i = 0; i < 21; ++i) {
                float v;
                v = fabsf(got_logits[0][i] - JEV_TV_LOGITS[c][i]);
                if (v > dl) dl = v;
                v = fabsf(got_probs[0][i] - JEV_TV_PROBS[c][i]);
                if (v > dp) dp = v;
            }
            for (a = 0; a < 3; ++a) {
                float v = fabsf(got_step[0][a] - JEV_TV_STEP[c][a]);
                if (v > ds) ds = v;
            }
            if (dl > worst_logits) worst_logits = dl;
            if (dp > worst_probs) worst_probs = dp;
            if (ds > worst_step) worst_step = ds;
            if (dl > JEV_TOL_LOGITS || dp > JEV_TOL_PROBS || ds > JEV_TOL_STEP) {
                failures++;
                printf("FAIL case %d: logits %.3e probs %.3e step %.3e\n", c, dl,
                       dp, ds);
            }
        }
    }

    printf("cases %d\n", JEV_TV_N);
    printf("max_abs_diff_logits %.3e (tol %.1e)\n", worst_logits,
           (double)JEV_TOL_LOGITS);
    printf("max_abs_diff_probs  %.3e (tol %.1e)\n", worst_probs,
           (double)JEV_TOL_PROBS);
    printf("max_abs_diff_step   %.3e (tol %.1e)\n", worst_step,
           (double)JEV_TOL_STEP);
    printf("failures %d\n", failures);
    return failures == 0 ? 0 : 1;
}
